'use client';
import type * as PageTree from 'fumadocs-core/page-tree';
import {
  type BaseLayoutProps,
  type BaseSlots,
  type BaseSlotsProps,
  baseSlots,
  getLayoutTabs,
  type GetLayoutTabsOptions,
  type LayoutTab,
  type LinkItemType,
  useLinkItems,
} from 'local:<dir>/shared/index.tsx';
import { TreeContextProvider } from '@fumadocs/base-ui/contexts/tree';
import { createContext, type FC, use, useMemo } from 'react';
import {
  drawerHandle,
  Sidebar,
  SidebarDrawer,
  SidebarProvider,
  useSidebar,
  type SidebarProps,
  type SidebarProviderProps,
  type SidebarDrawerProps,
} from 'local:<dir>/glass/slots/sidebar.tsx';
import { Header, type HeaderProps } from 'local:<dir>/glass/slots/header.tsx';
import type { Drawer } from '@base-ui/react';

export interface GlassSlots extends BaseSlots {
  header: FC<HeaderProps>;
  sidebar: {
    main: FC<SidebarProps>;
    provider: FC<SidebarProviderProps>;
    use: typeof useSidebar;
    drawer: FC<SidebarDrawerProps>;
    drawerHandle: Drawer.Handle<unknown>;
  };
}

export interface GlassLayoutProps extends BaseLayoutProps {
  tree: PageTree.Root;
  tabs?: LayoutTab[] | GetLayoutTabsOptions | false;
  aiChat?: {
    open: boolean;
    onOpenChange: (v: boolean) => void;
  };
  slots?: Partial<GlassSlots>;
  sidebar?: Omit<SidebarProviderProps, 'children'>;
}

interface SlotsProps extends BaseSlotsProps<GlassLayoutProps> {
  tabs: LayoutTab[];
  aiChat?: GlassLayoutProps['aiChat'];
}

const LayoutContext = createContext<{
  props: SlotsProps;
  navItems: LinkItemType[];
  menuItems: LinkItemType[];
  slots: GlassSlots;
} | null>(null);

export function useGlassLayout() {
  const context = use(LayoutContext);
  if (!context)
    throw new Error(
      'Please use Glass layout components under <GlassLayout /> (`fumadocs-ui/layouts/glass`).',
    );
  return context;
}

const { useBaseSlots } = baseSlots({
  useProps() {
    return useGlassLayout().props;
  },
});

export function GlassLayout(props: GlassLayoutProps) {
  const { tree, tabs: defaultTabs, aiChat, children, slots: defaultSlots = {} } = props;
  const linkItems = useLinkItems(props);
  const { baseSlots, baseProps } = useBaseSlots(props);

  const tabs = useMemo(() => {
    if (Array.isArray(defaultTabs)) {
      return defaultTabs;
    }
    if (typeof defaultTabs === 'object') {
      return getLayoutTabs(tree, defaultTabs);
    }
    if (defaultTabs !== false) {
      return getLayoutTabs(tree);
    }
    return [];
  }, [tree, defaultTabs]);

  const slots: GlassSlots = {
    ...baseSlots,
    header: defaultSlots.header ?? Header,
    sidebar: defaultSlots.sidebar ?? {
      drawer: SidebarDrawer,
      drawerHandle,
      main: Sidebar,
      provider: SidebarProvider,
      use: useSidebar,
    },
  };

  const leftSpace = 'calc(50% - var(--fd-main-width)/2 - var(--fd-left-width))';
  return (
    <LayoutContext
      value={{
        props: {
          tabs,
          aiChat,
          ...baseProps,
        },
        slots,
        ...linkItems,
      }}
    >
      <slots.sidebar.provider {...props.sidebar}>
        <TreeContextProvider tree={tree}>
          <div
            id="fd-glass-layout"
            className="grid overflow-x-clip min-h-dvh [--fd-main-width:900px] [--fd-left-width:0px] [--fd-right-width:0px]"
            style={{
              gridTemplate: `"left left-margin main right-margin right" 1fr / var(--fd-left-width) ${leftSpace} 1fr calc(50% - var(--fd-main-width)/2 - var(--fd-right-width) + min(${leftSpace}, 0px)) var(--fd-right-width)`,
            }}
          >
            <slots.sidebar.drawer />
            <slots.sidebar.main />
            <slots.header />
            {children}
          </div>
        </TreeContextProvider>
      </slots.sidebar.provider>
    </LayoutContext>
  );
}

'use client';
import { type ComponentProps, createContext, use, useEffect, useState } from 'react';
import { cn } from 'local:utils/cn.ts';
import { useTranslations } from '@fuma-translate/react';
import { buttonVariants } from 'local:components/ui/button.tsx';
import { Edit } from 'lucide-react';
import { Footer } from 'local:<dir>/glass/page/slots/footer.tsx';
import { Breadcrumb } from 'local:<dir>/glass/page/slots/breadcrumb.tsx';
import { TOC, type TOCProps, TOCProvider } from 'local:<dir>/glass/page/slots/toc.tsx';
import { TOCItemType } from 'fumadocs-core/toc';

export interface DocsPageProps extends ComponentProps<'article'> {
  toc?: TOCItemType[];

  /**
   * Extend the page to fill all available space
   *
   * @defaultValue false
   */
  full?: boolean | undefined;

  tableOfContent?: TOCProps;
}

const PageContext = createContext<{
  full: boolean;
} | null>(null);

export function useDocsPage() {
  const context = use(PageContext);
  if (!context)
    throw new Error(
      'Please use page components under <DocsPage /> (`fumadocs-ui/layouts/glass/page`).',
    );
  return context;
}

const Empty: never[] = [];

export function DocsPage({ full = false, toc = Empty, tableOfContent, children }: DocsPageProps) {
  return (
    <PageContext
      value={{
        full,
      }}
    >
      <TOCProvider toc={toc}>
        <div
          data-fd-full={full}
          className={cn(
            'flex flex-col gap-2 p-6 pb-16 min-w-0 [grid-area:main] md:pt-16 md:pb-8',
            full && 'layout:[--fd-main-width:1200px]',
          )}
        >
          <Breadcrumb />
          {children}
          <Footer />
        </div>
        <TOC {...tableOfContent} />
      </TOCProvider>
    </PageContext>
  );
}

export function EditOnGitHub(props: ComponentProps<'a'>) {
  const t = useTranslations({ note: 'edit page' });

  return (
    <a
      target="_blank"
      rel="noreferrer noopener"
      {...props}
      className={cn(
        buttonVariants({
          color: 'secondary',
          size: 'sm',
        }),
        'gap-1.5 not-prose',
        props.className,
      )}
    >
      {props.children ?? (
        <>
          <Edit className="size-3.5" />
          {t('Edit on GitHub')}
        </>
      )}
    </a>
  );
}

/**
 * Add typography styles
 */
export function DocsBody({ children, className, ...props }: ComponentProps<'div'>) {
  return (
    <div {...props} className={cn('prose flex-1', className)}>
      {children}
    </div>
  );
}

export function DocsDescription({ children, className, ...props }: ComponentProps<'p'>) {
  // Don't render if no description provided
  if (children === undefined) return null;

  return (
    <p {...props} className={cn('mb-8 text-lg text-fd-muted-foreground', className)}>
      {children}
    </p>
  );
}

export function DocsTitle({ children, className, ...props }: ComponentProps<'h1'>) {
  return (
    <h1 {...props} className={cn('text-[1.75em] font-semibold', className)}>
      {children}
    </h1>
  );
}

export function PageLastUpdate({
  date: value,
  ...props
}: Omit<ComponentProps<'p'>, 'children'> & { date: Date }) {
  const t = useTranslations({ note: 'page footer' });
  const [date, setDate] = useState('');

  useEffect(() => {
    // to the timezone of client
    setDate(value.toLocaleDateString());
  }, [value]);

  return (
    <p {...props} className={cn('text-sm text-fd-muted-foreground', props.className)}>
      {t('Last updated on')} {date}
    </p>
  );
}

export { MarkdownCopyButton, ViewOptionsPopover } from 'local:<dir>/ai/page-actions.tsx';
